import {incomeTax,spouseEligible} from './model.mjs?v=2.5';
// V2.3 interaction helpers. Financial and tax formulas remain in model.mjs.
export const STORAGE_KEY='fp.plan.v2.3';
export function parseAmount(raw){
 const s=String(raw).trim();
 if(!s)return null;
 if(!/^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d*)?$/.test(s))throw Error('กรอกตัวเลข เช่น 1,250,000.50');
 const n=Number(s.replaceAll(',',''));if(!Number.isFinite(n)||n>1e12)throw Error('จำนวนเงินต้องไม่เกิน 1 ล้านล้าน');return n;
}
export const formatAmount=n=>n==null?'':new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:10}).format(n);
export function fieldKey(s,path){const [kind,i,...rest]=path.split('.');return Array.isArray(s[kind])?`${kind}.${s[kind][i]?.id}.${rest.join('.')}`:path}
export function meta(s,imported=false){if(!s.ux)s.ux={answers:{},known:{},unknown:{},visited:{},skipped:{},reviewed:{},imported};return s.ux}
export function normalizeMeta(s){const u=s.ux;if(!u)return meta(s,true);if(typeof u!=='object'||Array.isArray(u)||typeof u.imported!=='boolean')throw Error('ข้อมูลสถานะไม่ถูกต้อง');for(const k of ['answers','known','unknown','visited','skipped','reviewed']){if(!u[k]||typeof u[k]!=='object'||Array.isArray(u[k]))throw Error('ข้อมูลสถานะไม่ครบ');for(const [key,v]of Object.entries(u[k])){if(key.length>200||['__proto__','constructor','prototype'].includes(key))throw Error('สถานะไม่ถูกต้อง');if(k==='answers'?!['yes','no',''].includes(v):typeof v!=='boolean')throw Error('สถานะไม่ถูกต้อง')}}return u}
export function pack(s){return {app:'FP',version:7,appVersion:'2.5.0',savedAt:new Date().toISOString(),data:s}}
export function storageController(storage,decode){let blocked=false;return {
 load(){try{const raw=storage.getItem(STORAGE_KEY);if(!raw)return {state:null};const payload=JSON.parse(raw);const state=decode(payload);if(payload.version>=6&&!state.ux)throw Error("ข้อมูลสถานะ V2.3 ไม่ครบ");normalizeMeta(state);return {state}}catch(error){blocked=true;return {error,blocked:true}}},
 save(s){if(blocked)return {ok:false,blocked:true};try{storage.setItem(STORAGE_KEY,JSON.stringify(pack(s)));return {ok:true}}catch(error){return {ok:false,error}}},
 clear(){try{storage.removeItem(STORAGE_KEY);blocked=false;return {ok:true}}catch(error){return {ok:false,error}}},
 get blocked(){return blocked}
}}
export function existing(s,k){return k==='pvd'?s.portfolios.some(p=>p.type==='PVD'):k==='portfolios'?s.portfolios.some(p=>p.type!=='PVD'):!!s[k]?.length}
export function answer(s,k){return existing(s,k)?'yes':meta(s).answers[k]||''}
export function missing(s,page){const u=meta(s),out=[];const need=(path,label,positive=false)=>{const key=fieldKey(s,path);const v=path.split('.').reduce((o,k)=>o?.[k],s);if(u.unknown[key]||(!u.imported&&!u.known[key])||v==null||v===''||(positive&&!(v>0)))out.push(label)};
 const group=(k,fields)=>{if(!answer(s,k))out.push('ระบุว่ามี'+({incomes:'รายรับ',expenses:'รายจ่าย',assets:'สินทรัพย์',debts:'หนี้',pvd:' PVD',policies:'ประกัน',portfolios:'พอร์ตลงทุน',goals:'เป้าหมาย'}[k]||k)+'หรือไม่');if(answer(s,k)==='yes'&&!existing(s,k))out.push('เพิ่มรายการ '+k);const rows=k==='pvd'?s.portfolios:s[k]||[];rows.forEach((r,i)=>{if(k==='pvd'&&r.type!=='PVD'||k==='portfolios'&&r.type==='PVD')return;if(!String(r.name||'').trim())out.push('ระบุชื่อรายการ');if(k==='policies'&&r.type==='annuity'){need(`policies.${i}.annuity`,'เงินบำนาญต่อปี');if(r.annuityEnd<r.annuityStart)out.push('ตรวจช่วงอายุรับบำนาญ')}if((k==='portfolios'||k==='pvd')&&r.payroll&&r.monthly>0&&!s.incomes.some(x=>x.id===r.incomeId&&x.frequency==='monthly'))out.push('ผูกกองทุนกับรายรับรายเดือน');if(k==='portfolios'&&['RMF','SSF','ThaiESG','ThaiESGX'].includes(r.type)&&!r.unlock)out.push(r.name+': วันที่เงินพร้อมใช้');for(const [f,label,pos]of fields)need(`${k==='pvd'?'portfolios':k}.${i}.${f}`,`${r.name}: ${label}`,pos)})};
 if(['finance','tax'].includes(page)&&s.incomes.some(r=>r.frequency==='monthly'&&r.endMonth<r.startMonth))out.push('เดือนเริ่มและสิ้นสุดรายรับไม่ถูกต้อง');if(page==='finance'){need('profile.name','ชื่อแผน');need('profile.age','อายุ',true);for(const k of ['incomes','expenses'])group(k,[['amount','จำนวนเงิน']]);group('assets',[['value','มูลค่า']]);group('debts',[['balance','ยอดหนี้'],['monthly','ค่างวด']]);group('pvd',[['value','มูลค่า'],['monthly','เงินสะสมต่อเดือน']])}
 if(page==='protection'){if(!answer(s,'debts'))out.push('ยืนยันหนี้สินในหน้าแรก');group('policies',[['premium','เบี้ย'],['death','ทุนชีวิต']]);need('protection.familyMonthly','เงินดูแลครอบครัว');need('protection.years','ระยะเวลาดูแล');need('protection.education','เงินการศึกษา');need('protection.available','สินทรัพย์ให้ครอบครัว')}
 if(page==='goals'){group('goals',[['target','เป้าหมาย',true],['years','ระยะเวลา',true],['monthly','เงินออม']]);group('portfolios',[['value','มูลค่า'],['monthly','เงินลงทุนต่อเดือน']])}
 if(page==='retirement'){for(const [f,label,pos]of [['age','อายุเกษียณ',true],['end','อายุสิ้นสุดแผน',true],['expense','ค่าใช้จ่าย',true],['social','บำนาญประกันสังคม'],['other','รายได้อื่น'],['monthly','เงินออมเพิ่ม']])need('retirement.'+f,label,pos);need('profile.age','อายุเจ้าของแผน',true);if(s.retirement.age<s.profile.age||s.retirement.end<=s.retirement.age)out.push('ลำดับอายุเกษียณไม่ถูกต้อง');if(!answer(s,'pvd')||!answer(s,'portfolios')||!answer(s,'policies'))out.push('ยืนยัน PVD พอร์ต และประกันในหน้าที่เกี่ยวข้อง')}
 if(page==='tax'){if(s.tax.spouse&&!spouseEligible(s))out.push('ยืนยันเงื่อนไขคู่สมรสก่อนใช้สิทธิ');if(!answer(s,'incomes'))out.push('ยืนยันรายรับในหน้าแรก');s.incomes.forEach((r,i)=>{if(r.taxInclude){const t=incomeTax(s,r);if(!t.coveredBy){if(r.taxSource==='estimate'){need(`incomes.${i}.amount`,r.name+': ยอดก่อนหัก');need(`incomes.${i}.taxDeduct`,r.name+': ภาษีหักต่องวด');if(r.amountMode!=='gross')out.push(r.name+': ต้องกรอกยอดก่อนหักเพื่อประมาณภาษี');}else{need(`incomes.${i}.gross`,r.name+': เงินได้ทั้งปี');need(`incomes.${i}.withheld`,r.name+': ภาษีที่หักแล้ว');}}if(r.method==='actual'&&['3','5','6','7','8'].includes(r.taxType))need(`incomes.${i}.costs`,r.name+': ค่าใช้จ่ายจริง');if(r.taxType==='8'&&r.method==='standard'&&!r.rate)out.push(r.name+': ยังไม่ยืนยันอัตราเหมาธุรกิจ')}});if(!answer(s,'policies')||!answer(s,'pvd')||!answer(s,'portfolios'))out.push('ยืนยันประกัน PVD และพอร์ตเพื่อเชื่อมสิทธิภาษี')}
 if(['finance','goals','retirement'].includes(page)){s.portfolios.forEach((r,i)=>{if(page==='retirement'&&r.purpose!=='retirement')return;if(page!=='finance'&&['RMF','SSF','ThaiESG','ThaiESGX'].includes(r.type)&&!r.unlock)out.push(r.name+': วันที่เงินพร้อมใช้');need(`portfolios.${i}.value`,r.name+': มูลค่าพอร์ต');need(`portfolios.${i}.monthly`,r.name+': เงินลงทุนต่อเดือน')});s.assets.forEach((r,i)=>{if(page==='finance'||r.kind==='cash'&&(page!=='retirement'||r.purpose==='retirement'))need(`assets.${i}.value`,r.name+': มูลค่าสินทรัพย์')})}
 if(['finance','protection','retirement'].includes(page)){s.policies.forEach((r,i)=>{need(`policies.${i}.premium`,r.name+': เบี้ย');if(page==='retirement'&&r.type==='annuity')need(`policies.${i}.annuity`,r.name+': บำนาญ')})}
 if(page==='protection')s.debts.forEach((r,i)=>need(`debts.${i}.balance`,r.name+': ยอดหนี้'));
 if(page==='finance')for(const k of ['policies','portfolios','goals'])if(!answer(s,k))out.push('ยืนยัน '+({policies:'ประกัน',portfolios:'พอร์ตลงทุน',goals:'เป้าหมาย'}[k])+' ในหน้าที่เกี่ยวข้อง เพื่อรวมภาระเบี้ยและการออม');
 if(page==='report'){for(const p of ['finance','protection','goals','retirement','tax'])if(!u.skipped[p]&&(missing(s,p).length||!u.reviewed[p]))out.push('ทบทวนหน้า '+p)}
 if(unknownFor(s,page))out.push('มีค่าที่ยังไม่ทราบ/ยังเว้นว่างในแผน ผลรวมที่เกี่ยวข้องยังไม่พร้อม');return [...new Set(out)]}
export function pageStatus(s,p){const u=meta(s);if(u.skipped[p])return 'เลือกข้าม';if(!missing(s,p).length&&u.reviewed[p])return 'กรอกครบ';if(u.visited[p]||u.imported)return 'กำลังกรอก';return 'ยังไม่เริ่ม'}
export function allocation(s){const rows=[...s.assets.filter(a=>a.kind==='cash'),...s.portfolios];return rows.reduce((a,r)=>{a[r.purpose==='unallocated'?'free':'allocated']+=r.value;return a},{allocated:0,free:0})}

// Scope unresolved inputs to calculations that consume them. Report checks its sections separately.
export function unknownFor(s,page){const keys=Object.entries(meta(s).unknown).filter(([,v])=>v).map(([k])=>k);const relevant=k=>{const [group,id,field]=k.split('.');if(page==='report')return true;if(page==='tax'){if(group==='profile')return false;if(group==='incomes'){const r=s.incomes.find(r=>r.id===id);if(!r?.taxInclude||incomeTax(s,r).coveredBy)return false;return (r.taxSource==='estimate'?['amount','taxDeduct','startMonth','endMonth']:['gross','withheld','costs','rate']).includes(field);}return group==='tax'||group==='policies'&&['taxLife','taxHealth','taxAnnuity'].includes(field)||group==='portfolios'&&['taxPaid','monthly'].includes(field)||group==='debts'&&field==='homeInterest'||group==='retirement'&&id==='socialOwnMonthly';}if(page==='finance')return group==='incomes'&&!['gross','withheld','rate','costs'].includes(field)||group==='expenses'||group==='assets'&&field==='value'||group==='debts'&&['balance','monthly','extra','rate'].includes(field)||group==='policies'&&field==='premium'||group==='portfolios'&&['value','monthly'].includes(field)||group==='goals'&&field==='monthly'||group==='retirement'&&['monthly','socialOwnMonthly'].includes(id)||group==='profile'&&id==='reserveMonths';if(page==='protection')return group==='protection'||group==='debts'&&field==='balance'||group==='policies'&&['death','ci','health','disability','premium'].includes(field);if(page==='retirement')return group==='retirement'||group==='profile'&&id==='age'||group==='assets'&&s.assets.find(r=>r.id===id)?.purpose==='retirement'||group==='portfolios'&&s.portfolios.find(r=>r.id===id)?.purpose==='retirement'&&['value','monthly','employer'].includes(field)||group==='policies'&&s.policies.find(r=>r.id===id)?.type==='annuity'&&['annuity','annuityStart','annuityEnd'].includes(field);if(page==='goals')return group==='goals'||group==='assets'||group==='portfolios'||group==='profile'&&id==='risk';return false;};return keys.some(relevant);}
